ROUTERS = {
    "users": """\"\"\"Users router — profile CRUD, admin user management.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import User\nfrom db.schemas import UserOut, UserUpdate, UserAdminUpdate, MessageResponse\nfrom utils.dependencies import get_current_user, require_admin\n\nrouter = APIRouter()\n\n@router.get(\"/me\", response_model=UserOut)\ndef get_profile(current_user: User = Depends(get_current_user)):\n    return current_user\n\n@router.put(\"/me\", response_model=UserOut)\ndef update_profile(payload: UserUpdate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    for k, v in payload.model_dump(exclude_unset=True).items():\n        setattr(current_user, k, v)\n    db.commit(); db.refresh(current_user)\n    return current_user\n\n@router.get(\"\", response_model=list[UserOut])\ndef list_users(skip: int = 0, limit: int = 50, current_user: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(User).offset(skip).limit(limit).all()\n\n@router.get(\"/{user_id}\", response_model=UserOut)\ndef get_user(user_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    u = db.query(User).filter(User.id == user_id).first()\n    if not u: raise HTTPException(404, \"User not found\")\n    return u\n\n@router.put(\"/{user_id}\", response_model=UserOut)\ndef admin_update_user(user_id: int, payload: UserAdminUpdate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    u = db.query(User).filter(User.id == user_id).first()\n    if not u: raise HTTPException(404, \"User not found\")\n    for k, v in payload.model_dump(exclude_unset=True).items():\n        setattr(u, k, v)\n    db.commit(); db.refresh(u)\n    return u\n""",

    "categories": """\"\"\"Categories router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, status\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Category\nfrom db.schemas import CategoryCreate, CategoryUpdate, CategoryOut\nfrom utils.dependencies import require_admin\nfrom db.models import User\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[CategoryOut])\ndef list_categories(db: Session = Depends(get_db)):\n    return db.query(Category).filter(Category.is_active == True).order_by(Category.sort_order).all()\n\n@router.get(\"/{category_id}\", response_model=CategoryOut)\ndef get_category(category_id: int, db: Session = Depends(get_db)):\n    c = db.query(Category).filter(Category.id == category_id).first()\n    if not c: raise HTTPException(404, \"Not found\")\n    return c\n\n@router.post(\"\", response_model=CategoryOut, status_code=status.HTTP_201_CREATED)\ndef create_category(payload: CategoryCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = Category(**payload.model_dump())\n    db.add(c); db.commit(); db.refresh(c)\n    return c\n\n@router.put(\"/{category_id}\", response_model=CategoryOut)\ndef update_category(category_id: int, payload: CategoryUpdate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = db.query(Category).filter(Category.id == category_id).first()\n    if not c: raise HTTPException(404, \"Not found\")\n    for k, v in payload.model_dump(exclude_unset=True).items(): setattr(c, k, v)\n    db.commit(); db.refresh(c)\n    return c\n\n@router.delete(\"/{category_id}\")\ndef delete_category(category_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = db.query(Category).filter(Category.id == category_id).first()\n    if not c: raise HTTPException(404, \"Not found\")\n    db.delete(c); db.commit()\n    return {\"message\": \"Deleted\"}\n""",

    "cart": """\"\"\"Cart router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import CartItem, Product, User\nfrom db.schemas import CartItemCreate, CartOut, CartItemOut, ProductListOut\nfrom utils.dependencies import get_current_user\nfrom decimal import Decimal\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=CartOut)\ndef get_cart(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    items = db.query(CartItem).filter(CartItem.user_id == current_user.id).all()\n    subtotal = sum((i.product.price * i.quantity) for i in items if i.product)\n    return CartOut(items=items, subtotal=subtotal, item_count=len(items))\n\n@router.post(\"/items\")\ndef add_to_cart(payload: CartItemCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    product = db.query(Product).filter(Product.id == payload.product_id, Product.is_active == True).first()\n    if not product: raise HTTPException(404, \"Product not found\")\n    existing = db.query(CartItem).filter(CartItem.user_id == current_user.id, CartItem.product_id == payload.product_id, CartItem.variant_id == payload.variant_id).first()\n    if existing:\n        existing.quantity += payload.quantity\n    else:\n        db.add(CartItem(user_id=current_user.id, **payload.model_dump()))\n    db.commit()\n    return {\"message\": \"Added to cart\"}\n\n@router.put(\"/items/{item_id}\")\ndef update_cart_item(item_id: int, quantity: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    item = db.query(CartItem).filter(CartItem.id == item_id, CartItem.user_id == current_user.id).first()\n    if not item: raise HTTPException(404, \"Item not found\")\n    if quantity <= 0:\n        db.delete(item)\n    else:\n        item.quantity = quantity\n    db.commit()\n    return {\"message\": \"Updated\"}\n\n@router.delete(\"/items/{item_id}\")\ndef remove_from_cart(item_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    item = db.query(CartItem).filter(CartItem.id == item_id, CartItem.user_id == current_user.id).first()\n    if not item: raise HTTPException(404, \"Item not found\")\n    db.delete(item); db.commit()\n    return {\"message\": \"Removed\"}\n\n@router.delete(\"\")\ndef clear_cart(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    db.query(CartItem).filter(CartItem.user_id == current_user.id).delete()\n    db.commit()\n    return {\"message\": \"Cart cleared\"}\n""",

    "orders": """\"\"\"Orders router.\"\"\"\nfrom __future__ import annotations\nimport math, random, string\nfrom fastapi import APIRouter, Depends, HTTPException, Query\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Order, OrderItem, Product, CartItem, Coupon, User\nfrom db.schemas import OrderCreate, OrderOut, OrderListOut, PaginatedOrders, OrderStatusUpdate\nfrom utils.dependencies import get_current_user, require_admin\nfrom utils.datetime_utils import utcnow\nfrom decimal import Decimal\n\nrouter = APIRouter()\n\ndef _gen_order_number():\n    return \"ORD-\" + \"\".join(random.choices(string.ascii_uppercase + string.digits, k=8))\n\n@router.get(\"\", response_model=PaginatedOrders)\ndef list_orders(page: int = Query(1, ge=1), size: int = Query(20), current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    q = db.query(Order)\n    if current_user.role == \"customer\":\n        q = q.filter(Order.customer_id == current_user.id)\n    total = q.count()\n    items = q.order_by(Order.created_at.desc()).offset((page-1)*size).limit(size).all()\n    return PaginatedOrders(items=items, total=total, page=page, size=size, pages=math.ceil(total/size) if total else 1)\n\n@router.get(\"/{order_id}\", response_model=OrderOut)\ndef get_order(order_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    o = db.query(Order).filter(Order.id == order_id).first()\n    if not o: raise HTTPException(404, \"Order not found\")\n    if current_user.role == \"customer\" and o.customer_id != current_user.id:\n        raise HTTPException(403, \"Not your order\")\n    return o\n\n@router.post(\"\", response_model=OrderOut, status_code=201)\ndef create_order(payload: OrderCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    subtotal = Decimal(\"0\")\n    order_items = []\n    for ci in payload.items:\n        p = db.query(Product).filter(Product.id == ci.product_id, Product.is_active == True).first()\n        if not p: raise HTTPException(400, f\"Product {ci.product_id} not available\")\n        line = ci.quantity * p.price\n        subtotal += line\n        order_items.append(OrderItem(product_id=p.id, product_name=p.name, product_image=p.image_url, quantity=ci.quantity, unit_price=p.price, total_price=line))\n    discount = Decimal(\"0\")\n    coupon_id = None\n    if payload.coupon_code:\n        coupon = db.query(Coupon).filter(Coupon.code == payload.coupon_code, Coupon.is_active == True).first()\n        if coupon:\n            if coupon.discount_type == \"percentage\":\n                discount = subtotal * coupon.discount_value / 100\n            else:\n                discount = coupon.discount_value\n            if coupon.maximum_discount:\n                discount = min(discount, coupon.maximum_discount)\n            coupon.usage_count += 1\n            coupon_id = coupon.id\n    total = subtotal - discount\n    order = Order(\n        order_number=_gen_order_number(),\n        customer_id=current_user.id,\n        status=\"pending\",\n        payment_method=payload.payment_method,\n        shipping_address=payload.shipping_address,\n        billing_address=payload.billing_address,\n        subtotal=subtotal, discount_amount=discount, total=total,\n        coupon_code=payload.coupon_code, coupon_id=coupon_id, notes=payload.notes,\n    )\n    db.add(order); db.flush()\n    for item in order_items:\n        item.order_id = order.id\n        db.add(item)\n    db.query(CartItem).filter(CartItem.user_id == current_user.id).delete()\n    db.commit(); db.refresh(order)\n    return order\n\n@router.put(\"/{order_id}/status\")\ndef update_order_status(order_id: int, payload: OrderStatusUpdate, current_user: User = Depends(require_admin), db: Session = Depends(get_db)):\n    o = db.query(Order).filter(Order.id == order_id).first()\n    if not o: raise HTTPException(404, \"Not found\")\n    o.status = payload.status\n    db.commit()\n    return {\"message\": \"Status updated\"}\n\n@router.post(\"/{order_id}/cancel\")\ndef cancel_order(order_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    o = db.query(Order).filter(Order.id == order_id).first()\n    if not o: raise HTTPException(404, \"Not found\")\n    if current_user.role == \"customer\" and o.customer_id != current_user.id:\n        raise HTTPException(403, \"Not your order\")\n    if o.status not in (\"pending\", \"confirmed\"):\n        raise HTTPException(400, \"Cannot cancel order in current status\")\n    o.status = \"cancelled\"; o.cancelled_at = utcnow()\n    db.commit()\n    return {\"message\": \"Order cancelled\"}\n""",

    "payments": """\"\"\"Payments router — Stripe integration.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, Request\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Order, Payment, User\nfrom db.schemas import PaymentIntentCreate, PaymentIntentOut\nfrom utils.dependencies import get_current_user\nfrom utils.config import settings\n\nrouter = APIRouter()\n\n@router.post(\"/create-intent\", response_model=PaymentIntentOut)\ndef create_payment_intent(payload: PaymentIntentCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    order = db.query(Order).filter(Order.id == payload.order_id).first()\n    if not order: raise HTTPException(404, \"Order not found\")\n    if order.customer_id != current_user.id: raise HTTPException(403, \"Not your order\")\n    try:\n        import stripe\n        stripe.api_key = settings.STRIPE_SECRET_KEY\n        intent = stripe.PaymentIntent.create(\n            amount=int(order.total * 100),\n            currency=payload.currency.lower(),\n            metadata={\"order_id\": order.id, \"order_number\": order.order_number},\n        )\n        order.payment_intent_id = intent.id\n        order.payment_provider = \"stripe\"\n        db.commit()\n        return PaymentIntentOut(client_secret=intent.client_secret, payment_intent_id=intent.id, amount=intent.amount, currency=intent.currency)\n    except Exception as e:\n        raise HTTPException(500, f\"Payment error: {e}\")\n\n@router.post(\"/webhook\")\nasync def stripe_webhook(request: Request, db: Session = Depends(get_db)):\n    payload = await request.body()\n    sig = request.headers.get(\"stripe-signature\", \"\")\n    try:\n        import stripe\n        stripe.api_key = settings.STRIPE_SECRET_KEY\n        event = stripe.Webhook.construct_event(payload, sig, settings.STRIPE_WEBHOOK_SECRET)\n    except Exception:\n        raise HTTPException(400, \"Invalid webhook\")\n    if event[\"type\"] == \"payment_intent.succeeded\":\n        pi = event[\"data\"][\"object\"]\n        order = db.query(Order).filter(Order.payment_intent_id == pi[\"id\"]).first()\n        if order:\n            order.payment_status = \"paid\"\n            order.status = \"confirmed\"\n            db.add(Payment(order_id=order.id, amount=order.total, provider=\"stripe\", provider_reference=pi[\"id\"], status=\"succeeded\"))\n            db.commit()\n    return {\"received\": True}\n""",

    "shipments": """\"\"\"Shipments router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Shipment, ShipmentEvent, User\nfrom db.schemas import ShipmentCreate, ShipmentOut, ShipmentUpdate, ShipmentEventCreate, ShipmentEventOut\nfrom utils.dependencies import get_current_user, require_admin, require_logistics\n\nrouter = APIRouter()\n\n@router.get(\"/{shipment_id}\", response_model=ShipmentOut)\ndef get_shipment(shipment_id: int, db: Session = Depends(get_db)):\n    s = db.query(Shipment).filter(Shipment.id == shipment_id).first()\n    if not s: raise HTTPException(404, \"Not found\")\n    return s\n\n@router.get(\"/track/{tracking_number}\", response_model=ShipmentOut)\ndef track_shipment(tracking_number: str, db: Session = Depends(get_db)):\n    s = db.query(Shipment).filter(Shipment.tracking_number == tracking_number).first()\n    if not s: raise HTTPException(404, \"Tracking number not found\")\n    return s\n\n@router.post(\"\", response_model=ShipmentOut, status_code=201)\ndef create_shipment(payload: ShipmentCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    s = Shipment(**payload.model_dump())\n    db.add(s); db.commit(); db.refresh(s)\n    return s\n\n@router.put(\"/{shipment_id}\", response_model=ShipmentOut)\ndef update_shipment(shipment_id: int, payload: ShipmentUpdate, _: User = Depends(require_logistics), db: Session = Depends(get_db)):\n    s = db.query(Shipment).filter(Shipment.id == shipment_id).first()\n    if not s: raise HTTPException(404, \"Not found\")\n    for k, v in payload.model_dump(exclude_unset=True).items(): setattr(s, k, v)\n    db.commit(); db.refresh(s)\n    return s\n\n@router.post(\"/{shipment_id}/events\", response_model=ShipmentEventOut, status_code=201)\ndef add_event(shipment_id: int, payload: ShipmentEventCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    s = db.query(Shipment).filter(Shipment.id == shipment_id).first()\n    if not s: raise HTTPException(404, \"Not found\")\n    event = ShipmentEvent(shipment_id=shipment_id, created_by=current_user.id, **payload.model_dump())\n    db.add(event); db.commit(); db.refresh(event)\n    return event\n""",

    "reviews": """\"\"\"Reviews router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, Query\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Review, User\nfrom db.schemas import ReviewCreate, ReviewOut\nfrom utils.dependencies import get_current_user\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[ReviewOut])\ndef list_reviews(product_id: int = Query(...), db: Session = Depends(get_db)):\n    return db.query(Review).filter(Review.product_id == product_id, Review.is_approved == True).all()\n\n@router.post(\"\", response_model=ReviewOut, status_code=201)\ndef create_review(payload: ReviewCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    existing = db.query(Review).filter(Review.product_id == payload.product_id, Review.user_id == current_user.id).first()\n    if existing: raise HTTPException(400, \"Already reviewed\")\n    review = Review(user_id=current_user.id, **payload.model_dump())\n    db.add(review); db.commit(); db.refresh(review)\n    return review\n\n@router.delete(\"/{review_id}\")\ndef delete_review(review_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    review = db.query(Review).filter(Review.id == review_id).first()\n    if not review: raise HTTPException(404, \"Not found\")\n    if review.user_id != current_user.id and current_user.role != \"admin\": raise HTTPException(403)\n    db.delete(review); db.commit()\n    return {\"message\": \"Deleted\"}\n""",

    "wishlist": """\"\"\"Wishlist router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import WishlistItem, Product, User\nfrom utils.dependencies import get_current_user\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef get_wishlist(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    return db.query(WishlistItem).filter(WishlistItem.user_id == current_user.id).all()\n\n@router.post(\"/{product_id}\", status_code=201)\ndef add_to_wishlist(product_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    if not db.query(Product).filter(Product.id == product_id).first(): raise HTTPException(404)\n    if db.query(WishlistItem).filter(WishlistItem.user_id == current_user.id, WishlistItem.product_id == product_id).first():\n        return {\"message\": \"Already in wishlist\"}\n    db.add(WishlistItem(user_id=current_user.id, product_id=product_id))\n    db.commit()\n    return {\"message\": \"Added\"}\n\n@router.delete(\"/{product_id}\")\ndef remove_from_wishlist(product_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    item = db.query(WishlistItem).filter(WishlistItem.user_id == current_user.id, WishlistItem.product_id == product_id).first()\n    if not item: raise HTTPException(404)\n    db.delete(item); db.commit()\n    return {\"message\": \"Removed\"}\n""",

    "addresses": """\"\"\"Addresses router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Address, User\nfrom db.schemas import AddressCreate, AddressOut\nfrom utils.dependencies import get_current_user\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[AddressOut])\ndef list_addresses(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    return db.query(Address).filter(Address.user_id == current_user.id).all()\n\n@router.post(\"\", response_model=AddressOut, status_code=201)\ndef create_address(payload: AddressCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    if payload.is_default:\n        db.query(Address).filter(Address.user_id == current_user.id).update({\"is_default\": False})\n    addr = Address(user_id=current_user.id, **payload.model_dump())\n    db.add(addr); db.commit(); db.refresh(addr)\n    return addr\n\n@router.put(\"/{address_id}\", response_model=AddressOut)\ndef update_address(address_id: int, payload: AddressCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    a = db.query(Address).filter(Address.id == address_id, Address.user_id == current_user.id).first()\n    if not a: raise HTTPException(404)\n    for k, v in payload.model_dump().items(): setattr(a, k, v)\n    db.commit(); db.refresh(a)\n    return a\n\n@router.delete(\"/{address_id}\")\ndef delete_address(address_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    a = db.query(Address).filter(Address.id == address_id, Address.user_id == current_user.id).first()\n    if not a: raise HTTPException(404)\n    db.delete(a); db.commit()\n    return {\"message\": \"Deleted\"}\n""",

    "notifications": """\"\"\"Notifications router.\"\"\"\nfrom fastapi import APIRouter, Depends\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Notification, User\nfrom db.schemas import NotificationOut\nfrom utils.dependencies import get_current_user\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[NotificationOut])\ndef list_notifications(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    return db.query(Notification).filter(Notification.user_id == current_user.id).order_by(Notification.created_at.desc()).limit(50).all()\n\n@router.post(\"/{notification_id}/read\")\ndef mark_read(notification_id: int, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    n = db.query(Notification).filter(Notification.id == notification_id, Notification.user_id == current_user.id).first()\n    if n: n.is_read = True; db.commit()\n    return {\"message\": \"Marked as read\"}\n\n@router.post(\"/read-all\")\ndef mark_all_read(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    db.query(Notification).filter(Notification.user_id == current_user.id, Notification.is_read == False).update({\"is_read\": True})\n    db.commit()\n    return {\"message\": \"All marked as read\"}\n""",

    "coupons": """\"\"\"Coupons router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Coupon, User\nfrom db.schemas import CouponCreate, CouponOut, CouponValidateRequest, CouponValidateResponse\nfrom utils.dependencies import get_current_user, require_admin\nfrom utils.datetime_utils import utcnow\nfrom decimal import Decimal\n\nrouter = APIRouter()\n\n@router.post(\"/validate\", response_model=CouponValidateResponse)\ndef validate_coupon(payload: CouponValidateRequest, _: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    coupon = db.query(Coupon).filter(Coupon.code == payload.code, Coupon.is_active == True).first()\n    if not coupon: return CouponValidateResponse(valid=False, discount_amount=Decimal(\"0\"), message=\"Coupon not found\")\n    now = utcnow()\n    if coupon.expires_at and coupon.expires_at < now: return CouponValidateResponse(valid=False, discount_amount=Decimal(\"0\"), message=\"Coupon expired\")\n    if coupon.starts_at and coupon.starts_at > now: return CouponValidateResponse(valid=False, discount_amount=Decimal(\"0\"), message=\"Coupon not yet active\")\n    if coupon.usage_limit and coupon.usage_count >= coupon.usage_limit: return CouponValidateResponse(valid=False, discount_amount=Decimal(\"0\"), message=\"Coupon usage limit reached\")\n    if payload.order_total < coupon.minimum_order: return CouponValidateResponse(valid=False, discount_amount=Decimal(\"0\"), message=f\"Minimum order {coupon.minimum_order}\")\n    if coupon.discount_type == \"percentage\":\n        discount = payload.order_total * coupon.discount_value / 100\n    else:\n        discount = coupon.discount_value\n    if coupon.maximum_discount: discount = min(discount, coupon.maximum_discount)\n    return CouponValidateResponse(valid=True, discount_amount=discount, coupon=coupon)\n\n@router.get(\"\", response_model=list[CouponOut])\ndef list_coupons(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(Coupon).all()\n\n@router.post(\"\", response_model=CouponOut, status_code=201)\ndef create_coupon(payload: CouponCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = Coupon(**payload.model_dump())\n    db.add(c); db.commit(); db.refresh(c)\n    return c\n\n@router.delete(\"/{coupon_id}\")\ndef delete_coupon(coupon_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = db.query(Coupon).filter(Coupon.id == coupon_id).first()\n    if not c: raise HTTPException(404)\n    db.delete(c); db.commit()\n    return {\"message\": \"Deleted\"}\n""",

    "banners": """\"\"\"Banners router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Banner, User\nfrom db.schemas import BannerCreate, BannerOut\nfrom utils.dependencies import require_admin\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[BannerOut])\ndef list_banners(position: str = None, db: Session = Depends(get_db)):\n    q = db.query(Banner).filter(Banner.is_active == True)\n    if position: q = q.filter(Banner.position == position)\n    return q.order_by(Banner.sort_order).all()\n\n@router.post(\"\", response_model=BannerOut, status_code=201)\ndef create_banner(payload: BannerCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    b = Banner(**payload.model_dump())\n    db.add(b); db.commit(); db.refresh(b)\n    return b\n\n@router.put(\"/{banner_id}\", response_model=BannerOut)\ndef update_banner(banner_id: int, payload: BannerCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    b = db.query(Banner).filter(Banner.id == banner_id).first()\n    if not b: raise HTTPException(404)\n    for k, v in payload.model_dump().items(): setattr(b, k, v)\n    db.commit(); db.refresh(b)\n    return b\n\n@router.delete(\"/{banner_id}\")\ndef delete_banner(banner_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    b = db.query(Banner).filter(Banner.id == banner_id).first()\n    if not b: raise HTTPException(404)\n    db.delete(b); db.commit()\n    return {\"message\": \"Deleted\"}\n""",

    "flash_sales": """\"\"\"Flash sales router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import FlashSale, FlashSaleItem, User\nfrom db.schemas import FlashSaleCreate, FlashSaleOut\nfrom utils.dependencies import require_admin\nfrom utils.datetime_utils import utcnow\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[FlashSaleOut])\ndef list_flash_sales(active_only: bool = True, db: Session = Depends(get_db)):\n    q = db.query(FlashSale)\n    if active_only:\n        now = utcnow()\n        q = q.filter(FlashSale.is_active == True, FlashSale.starts_at <= now, FlashSale.ends_at >= now)\n    return q.all()\n\n@router.get(\"/{sale_id}\", response_model=FlashSaleOut)\ndef get_flash_sale(sale_id: int, db: Session = Depends(get_db)):\n    s = db.query(FlashSale).filter(FlashSale.id == sale_id).first()\n    if not s: raise HTTPException(404)\n    return s\n\n@router.post(\"\", response_model=FlashSaleOut, status_code=201)\ndef create_flash_sale(payload: FlashSaleCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    items_data = payload.items\n    sale = FlashSale(**payload.model_dump(exclude={\"items\"}))\n    db.add(sale); db.flush()\n    for item in items_data:\n        db.add(FlashSaleItem(flash_sale_id=sale.id, **item.model_dump()))\n    db.commit(); db.refresh(sale)\n    return sale\n""",

    "tickets": """\"\"\"Support tickets router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import SupportTicket, TicketMessage, User\nfrom db.schemas import TicketCreate, TicketMessageCreate, TicketOut\nfrom utils.dependencies import get_current_user, require_staff\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[TicketOut])\ndef list_tickets(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    q = db.query(SupportTicket)\n    if current_user.role == \"customer\": q = q.filter(SupportTicket.user_id == current_user.id)\n    return q.order_by(SupportTicket.created_at.desc()).all()\n\n@router.post(\"\", response_model=TicketOut, status_code=201)\ndef create_ticket(payload: TicketCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    ticket = SupportTicket(user_id=current_user.id, **payload.model_dump())\n    db.add(ticket); db.commit(); db.refresh(ticket)\n    return ticket\n\n@router.post(\"/{ticket_id}/messages\", status_code=201)\ndef add_message(ticket_id: int, payload: TicketMessageCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    ticket = db.query(SupportTicket).filter(SupportTicket.id == ticket_id).first()\n    if not ticket: raise HTTPException(404)\n    msg = TicketMessage(ticket_id=ticket_id, sender_id=current_user.id, **payload.model_dump())\n    db.add(msg); db.commit(); db.refresh(msg)\n    return msg\n""",

    "returns": """\"\"\"Returns router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import ReturnRequest, Order, User\nfrom db.schemas import ReturnRequestCreate, ReturnRequestOut\nfrom utils.dependencies import get_current_user, require_admin\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[ReturnRequestOut])\ndef list_returns(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    q = db.query(ReturnRequest)\n    if current_user.role == \"customer\": q = q.filter(ReturnRequest.customer_id == current_user.id)\n    return q.order_by(ReturnRequest.created_at.desc()).all()\n\n@router.post(\"\", response_model=ReturnRequestOut, status_code=201)\ndef create_return(payload: ReturnRequestCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    order = db.query(Order).filter(Order.id == payload.order_id, Order.customer_id == current_user.id).first()\n    if not order: raise HTTPException(403, \"Order not found or not yours\")\n    if order.status not in (\"delivered\",): raise HTTPException(400, \"Order not eligible for return\")\n    req = ReturnRequest(customer_id=current_user.id, **payload.model_dump())\n    db.add(req); db.commit(); db.refresh(req)\n    return req\n\n@router.put(\"/{return_id}/status\")\ndef update_return_status(return_id: int, status: str, notes: str = None, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    r = db.query(ReturnRequest).filter(ReturnRequest.id == return_id).first()\n    if not r: raise HTTPException(404)\n    r.status = status\n    if notes: r.resolution_notes = notes\n    db.commit()\n    return {\"message\": \"Updated\"}\n""",

    "search": """\"\"\"Search router.\"\"\"\nfrom fastapi import APIRouter, Depends, Query\nfrom sqlalchemy import or_\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Product\nfrom db.schemas import ProductListOut\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[ProductListOut])\ndef search(q: str = Query(..., min_length=1), limit: int = 20, db: Session = Depends(get_db)):\n    products = db.query(Product).filter(\n        Product.is_active == True,\n        or_(Product.name.ilike(f\"%{q}%\"), Product.description.ilike(f\"%{q}%\"), Product.category.ilike(f\"%{q}%\"))\n    ).limit(limit).all()\n    return products\n""",

    "upload": """\"\"\"File upload router.\"\"\"\nfrom __future__ import annotations\nimport os, uuid\nfrom fastapi import APIRouter, Depends, File, HTTPException, UploadFile\nfrom utils.dependencies import get_current_user\nfrom utils.config import settings\nfrom db.models import User\n\nrouter = APIRouter()\n\nALLOWED_TYPES = {\"image/jpeg\", \"image/png\", \"image/webp\", \"image/gif\", \"application/pdf\"}\nMAX_SIZE = settings.MAX_UPLOAD_SIZE_MB * 1024 * 1024\n\n@router.post(\"/{folder}\")\nasync def upload_file(folder: str, file: UploadFile = File(...), current_user: User = Depends(get_current_user)):\n    if folder not in {\"products\", \"banners\", \"avatars\", \"documents\", \"suppliers\"}:\n        raise HTTPException(400, \"Invalid folder\")\n    if file.content_type not in ALLOWED_TYPES:\n        raise HTTPException(400, \"File type not allowed\")\n    content = await file.read()\n    if len(content) > MAX_SIZE:\n        raise HTTPException(400, f\"File too large (max {settings.MAX_UPLOAD_SIZE_MB}MB)\")\n    ext = file.filename.rsplit(\".\", 1)[-1] if \".\" in (file.filename or \"\") else \"bin\"\n    filename = f\"{uuid.uuid4().hex}.{ext}\"\n    filepath = os.path.join(settings.UPLOAD_DIR, folder, filename)\n    os.makedirs(os.path.dirname(filepath), exist_ok=True)\n    with open(filepath, \"wb\") as f:\n        f.write(content)\n    return {\"url\": f\"/uploads/{folder}/{filename}\", \"filename\": filename}\n""",

    "referrals": """\"\"\"Referrals router.\"\"\"\nimport secrets\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Referral, User\nfrom utils.dependencies import get_current_user\n\nrouter = APIRouter()\n\n@router.get(\"/my-code\")\ndef get_referral_code(current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    referral = db.query(Referral).filter(Referral.referrer_id == current_user.id).first()\n    if not referral:\n        code = secrets.token_urlsafe(8).upper()\n        referral = Referral(referrer_id=current_user.id, referral_code=code)\n        db.add(referral); db.commit(); db.refresh(referral)\n    return {\"referral_code\": referral.referral_code, \"status\": referral.status}\n""",

    "chatbot": """\"\"\"Chatbot router — AI product assistant.\"\"\"\nfrom fastapi import APIRouter, Depends\nfrom pydantic import BaseModel\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Product\nfrom utils.dependencies import get_current_user\nfrom db.models import User\nfrom typing import Optional\n\nrouter = APIRouter()\n\nclass ChatRequest(BaseModel):\n    message: str\n    session_id: Optional[str] = None\n\n@router.post(\"\")\ndef chat(payload: ChatRequest, db: Session = Depends(get_db)):\n    products = db.query(Product).filter(Product.is_active == True, Product.name.ilike(f\"%{payload.message}%\")).limit(5).all()\n    if products:\n        suggestions = [{\"id\": p.id, \"name\": p.name, \"price\": float(p.price), \"image\": p.image_url} for p in products]\n        return {\"response\": f\"I found {len(products)} matching products!\", \"products\": suggestions}\n    return {\"response\": \"I couldn't find specific products, but feel free to browse our catalog!\", \"products\": []}\n""",

    "ai_image": """\"\"\"AI image router — product image analysis.\"\"\"\nfrom fastapi import APIRouter, Depends, File, UploadFile, HTTPException\nfrom utils.dependencies import require_supplier\nfrom utils.config import settings\nfrom db.models import User\n\nrouter = APIRouter()\n\n@router.post(\"/analyze-image\")\nasync def analyze_image(file: UploadFile = File(...), current_user: User = Depends(require_supplier)):\n    if not settings.OPENAI_API_KEY:\n        raise HTTPException(503, \"AI service not configured\")\n    content = await file.read()\n    if len(content) > 10 * 1024 * 1024:\n        raise HTTPException(400, \"Image too large\")\n    # TODO: integrate OpenAI Vision for image analysis\n    return {\"tags\": [], \"description\": \"AI analysis coming soon\", \"suggested_category\": None}\n""",

    "supplier_profile": """\"\"\"Supplier profile router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import SupplierProfile, User\nfrom db.schemas import SupplierProfileCreate, SupplierProfileOut, SupplierProfileUpdate\nfrom utils.dependencies import get_current_user, require_supplier\nfrom utils.slug import generate_slug\n\nrouter = APIRouter()\n\n@router.get(\"/profile\", response_model=SupplierProfileOut)\ndef get_supplier_profile(current_user: User = Depends(require_supplier), db: Session = Depends(get_db)):\n    profile = db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first()\n    if not profile: raise HTTPException(404, \"Profile not found\")\n    return profile\n\n@router.post(\"/profile\", response_model=SupplierProfileOut, status_code=201)\ndef create_supplier_profile(payload: SupplierProfileCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    if db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first():\n        raise HTTPException(400, \"Profile already exists\")\n    profile = SupplierProfile(user_id=current_user.id, slug=generate_slug(payload.business_name), **payload.model_dump())\n    db.add(profile); db.commit(); db.refresh(profile)\n    current_user.role = \"supplier\"; db.commit()\n    return profile\n\n@router.put(\"/profile\", response_model=SupplierProfileOut)\ndef update_supplier_profile(payload: SupplierProfileUpdate, current_user: User = Depends(require_supplier), db: Session = Depends(get_db)):\n    profile = db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first()\n    if not profile: raise HTTPException(404)\n    for k, v in payload.model_dump(exclude_unset=True).items(): setattr(profile, k, v)\n    db.commit(); db.refresh(profile)\n    return profile\n""",

    "supplier_products": """\"\"\"Supplier products sub-router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, Query\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Product, SupplierProfile, User\nfrom db.schemas import ProductOut, ProductCreate, ProductUpdate\nfrom utils.dependencies import require_supplier\nimport math\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef list_my_products(page: int = Query(1, ge=1), size: int = Query(20), current_user: User = Depends(require_supplier), db: Session = Depends(get_db)):\n    supplier = db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first()\n    if not supplier: raise HTTPException(404, \"Supplier profile not found\")\n    q = db.query(Product).filter(Product.supplier_id == supplier.id)\n    total = q.count()\n    items = q.offset((page-1)*size).limit(size).all()\n    return {\"items\": items, \"total\": total, \"page\": page, \"size\": size, \"pages\": math.ceil(total/size) if total else 1}\n""",

    "supplier_orders": """\"\"\"Supplier orders sub-router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Order, OrderItem, SupplierProfile, User\nfrom utils.dependencies import require_supplier\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef list_supplier_orders(current_user: User = Depends(require_supplier), db: Session = Depends(get_db)):\n    supplier = db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first()\n    if not supplier: raise HTTPException(404)\n    orders = db.query(Order).join(OrderItem).filter(OrderItem.supplier_id == supplier.id).distinct().all()\n    return orders\n""",

    "supplier_analytics": """\"\"\"Supplier analytics sub-router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom sqlalchemy import func\nfrom db.database import get_db\nfrom db.models import Order, OrderItem, Product, SupplierProfile, User\nfrom utils.dependencies import require_supplier\n\nrouter = APIRouter()\n\n@router.get(\"/summary\")\ndef analytics_summary(current_user: User = Depends(require_supplier), db: Session = Depends(get_db)):\n    supplier = db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first()\n    if not supplier: raise HTTPException(404)\n    total_products = db.query(func.count(Product.id)).filter(Product.supplier_id == supplier.id).scalar()\n    total_sales = db.query(func.coalesce(func.sum(OrderItem.total_price), 0)).filter(OrderItem.supplier_id == supplier.id).scalar()\n    total_orders = db.query(func.count(func.distinct(OrderItem.order_id))).filter(OrderItem.supplier_id == supplier.id).scalar()\n    return {\"total_products\": total_products, \"total_sales\": float(total_sales), \"total_orders\": total_orders}\n""",

    "supplier_payouts": """\"\"\"Supplier payouts sub-router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Payout, SupplierProfile, User\nfrom db.schemas import PayoutOut\nfrom utils.dependencies import require_supplier\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[PayoutOut])\ndef list_payouts(current_user: User = Depends(require_supplier), db: Session = Depends(get_db)):\n    supplier = db.query(SupplierProfile).filter(SupplierProfile.user_id == current_user.id).first()\n    if not supplier: raise HTTPException(404)\n    return db.query(Payout).filter(Payout.supplier_id == supplier.id).order_by(Payout.created_at.desc()).all()\n""",

    "admin_users": """\"\"\"Admin users router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, Query\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import User\nfrom db.schemas import UserOut, UserAdminUpdate\nfrom utils.dependencies import require_admin\nimport math\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef list_users(page: int = Query(1, ge=1), size: int = Query(50), role: str = None, search: str = None, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    q = db.query(User)\n    if role: q = q.filter(User.role == role)\n    if search: q = q.filter(User.email.ilike(f\"%{search}%\") | User.full_name.ilike(f\"%{search}%\"))\n    total = q.count()\n    items = q.offset((page-1)*size).limit(size).all()\n    return {\"items\": items, \"total\": total, \"page\": page, \"pages\": math.ceil(total/size) if total else 1}\n\n@router.put(\"/{user_id}\", response_model=UserOut)\ndef update_user(user_id: int, payload: UserAdminUpdate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    u = db.query(User).filter(User.id == user_id).first()\n    if not u: raise HTTPException(404)\n    for k, v in payload.model_dump(exclude_unset=True).items(): setattr(u, k, v)\n    db.commit(); db.refresh(u)\n    return u\n\n@router.delete(\"/{user_id}\")\ndef deactivate_user(user_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    u = db.query(User).filter(User.id == user_id).first()\n    if not u: raise HTTPException(404)\n    u.is_active = False; db.commit()\n    return {\"message\": \"User deactivated\"}\n""",

    "admin_products": """\"\"\"Admin products router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, Query\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Product, User\nfrom db.schemas import ProductOut\nfrom utils.dependencies import require_admin\nimport math\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef list_all_products(page: int = Query(1, ge=1), size: int = Query(50), moderation_status: str = None, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    q = db.query(Product)\n    if moderation_status: q = q.filter(Product.moderation_status == moderation_status)\n    total = q.count()\n    items = q.offset((page-1)*size).limit(size).all()\n    return {\"items\": items, \"total\": total, \"page\": page, \"pages\": math.ceil(total/size) if total else 1}\n\n@router.put(\"/{product_id}/approve\")\ndef approve_product(product_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    p = db.query(Product).filter(Product.id == product_id).first()\n    if not p: raise HTTPException(404)\n    p.moderation_status = \"approved\"; p.is_verified = True\n    db.commit()\n    return {\"message\": \"Product approved\"}\n\n@router.put(\"/{product_id}/reject\")\ndef reject_product(product_id: int, reason: str = None, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    p = db.query(Product).filter(Product.id == product_id).first()\n    if not p: raise HTTPException(404)\n    p.moderation_status = \"rejected\"; p.moderation_notes = reason\n    db.commit()\n    return {\"message\": \"Product rejected\"}\n""",

    "admin_orders": """\"\"\"Admin orders router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException, Query\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Order, User\nfrom db.schemas import OrderOut, OrderStatusUpdate\nfrom utils.dependencies import require_admin\nimport math\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef list_all_orders(page: int = Query(1, ge=1), size: int = Query(50), status: str = None, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    q = db.query(Order)\n    if status: q = q.filter(Order.status == status)\n    total = q.count()\n    items = q.order_by(Order.created_at.desc()).offset((page-1)*size).limit(size).all()\n    return {\"items\": items, \"total\": total, \"page\": page, \"pages\": math.ceil(total/size) if total else 1}\n\n@router.put(\"/{order_id}/status\")\ndef update_status(order_id: int, payload: OrderStatusUpdate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    o = db.query(Order).filter(Order.id == order_id).first()\n    if not o: raise HTTPException(404)\n    o.status = payload.status\n    db.commit()\n    return {\"message\": \"Updated\"}\n""",

    "admin_analytics": """\"\"\"Admin analytics router.\"\"\"\nfrom fastapi import APIRouter, Depends\nfrom sqlalchemy import func\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Order, Product, User as UserModel, SupplierProfile\nfrom utils.dependencies import require_admin\nfrom db.models import User\n\nrouter = APIRouter()\n\n@router.get(\"/dashboard\")\ndef dashboard_summary(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    total_users = db.query(func.count(UserModel.id)).scalar()\n    total_suppliers = db.query(func.count(SupplierProfile.id)).scalar()\n    total_products = db.query(func.count(Product.id)).filter(Product.is_active == True).scalar()\n    total_orders = db.query(func.count(Order.id)).scalar()\n    total_revenue = db.query(func.coalesce(func.sum(Order.total), 0)).filter(Order.payment_status == \"paid\").scalar()\n    return {\"total_users\": total_users, \"total_suppliers\": total_suppliers, \"total_products\": total_products, \"total_orders\": total_orders, \"total_revenue\": float(total_revenue)}\n""",

    "admin_commission": """\"\"\"Admin commission router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import CommissionCategoryRate, CommissionBadgeTier, CommissionGlobalConfig, User\nfrom db.schemas import CommissionCategoryRateCreate, CommissionCategoryRateOut, CommissionBadgeTierCreate, CommissionBadgeTierOut\nfrom utils.dependencies import require_admin\n\nrouter = APIRouter()\n\n@router.get(\"/rates\", response_model=list[CommissionCategoryRateOut])\ndef list_rates(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(CommissionCategoryRate).all()\n\n@router.post(\"/rates\", response_model=CommissionCategoryRateOut, status_code=201)\ndef create_rate(payload: CommissionCategoryRateCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    r = CommissionCategoryRate(**payload.model_dump())\n    db.add(r); db.commit(); db.refresh(r)\n    return r\n\n@router.get(\"/badge-tiers\", response_model=list[CommissionBadgeTierOut])\ndef list_badge_tiers(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(CommissionBadgeTier).all()\n\n@router.post(\"/badge-tiers\", response_model=CommissionBadgeTierOut, status_code=201)\ndef create_badge_tier(payload: CommissionBadgeTierCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    t = CommissionBadgeTier(**payload.model_dump())\n    db.add(t); db.commit(); db.refresh(t)\n    return t\n""",

    "admin_payouts": """\"\"\"Admin payouts router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Payout, User\nfrom db.schemas import PayoutCreate, PayoutOut\nfrom utils.dependencies import require_admin\nfrom utils.datetime_utils import utcnow\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[PayoutOut])\ndef list_payouts(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(Payout).order_by(Payout.created_at.desc()).all()\n\n@router.post(\"\", response_model=PayoutOut, status_code=201)\ndef create_payout(payload: PayoutCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    p = Payout(**payload.model_dump())\n    db.add(p); db.commit(); db.refresh(p)\n    return p\n\n@router.put(\"/{payout_id}/process\")\ndef process_payout(payout_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    p = db.query(Payout).filter(Payout.id == payout_id).first()\n    if not p: raise HTTPException(404)\n    p.status = \"paid\"; p.processed_at = utcnow()\n    db.commit()\n    return {\"message\": \"Payout processed\"}\n""",

    "admin_logistics": """\"\"\"Admin logistics router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import LogisticsPartnerProfile, User\nfrom db.schemas import LogisticsPartnerProfileOut\nfrom utils.dependencies import require_admin\n\nrouter = APIRouter()\n\n@router.get(\"/partners\", response_model=list[LogisticsPartnerProfileOut])\ndef list_partners(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(LogisticsPartnerProfile).all()\n\n@router.put(\"/partners/{partner_id}/approve\")\ndef approve_partner(partner_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    p = db.query(LogisticsPartnerProfile).filter(LogisticsPartnerProfile.id == partner_id).first()\n    if not p: raise HTTPException(404)\n    p.verification_status = \"approved\"\n    db.commit()\n    return {\"message\": \"Partner approved\"}\n""",

    "admin_email": """\"\"\"Admin email campaign router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import EmailCampaign, User\nfrom db.schemas import EmailCampaignCreate, EmailCampaignOut\nfrom utils.dependencies import require_admin\n\nrouter = APIRouter()\n\n@router.get(\"\", response_model=list[EmailCampaignOut])\ndef list_campaigns(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(EmailCampaign).order_by(EmailCampaign.created_at.desc()).all()\n\n@router.post(\"\", response_model=EmailCampaignOut, status_code=201)\ndef create_campaign(payload: EmailCampaignCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = EmailCampaign(**payload.model_dump())\n    db.add(c); db.commit(); db.refresh(c)\n    return c\n\n@router.delete(\"/{campaign_id}\")\ndef delete_campaign(campaign_id: int, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    c = db.query(EmailCampaign).filter(EmailCampaign.id == campaign_id).first()\n    if not c: raise HTTPException(404)\n    db.delete(c); db.commit()\n    return {\"message\": \"Deleted\"}\n""",

    "admin_cash": """\"\"\"Admin cash management router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import CashAccount, CashTransaction, User\nfrom db.schemas import CashAccountCreate, CashAccountOut, CashTransactionCreate, CashTransactionOut\nfrom utils.dependencies import require_admin\nfrom decimal import Decimal\n\nrouter = APIRouter()\n\n@router.get(\"/accounts\", response_model=list[CashAccountOut])\ndef list_accounts(_: User = Depends(require_admin), db: Session = Depends(get_db)):\n    return db.query(CashAccount).filter(CashAccount.is_active == True).all()\n\n@router.post(\"/accounts\", response_model=CashAccountOut, status_code=201)\ndef create_account(payload: CashAccountCreate, _: User = Depends(require_admin), db: Session = Depends(get_db)):\n    a = CashAccount(**payload.model_dump())\n    db.add(a); db.commit(); db.refresh(a)\n    return a\n\n@router.post(\"/transactions\", response_model=CashTransactionOut, status_code=201)\ndef create_transaction(payload: CashTransactionCreate, current_user: User = Depends(require_admin), db: Session = Depends(get_db)):\n    account = db.query(CashAccount).filter(CashAccount.id == payload.account_id).first()\n    if not account: raise HTTPException(404, \"Account not found\")\n    if payload.transaction_type == \"debit\":\n        account.balance -= payload.amount\n    else:\n        account.balance += payload.amount\n    tx = CashTransaction(**payload.model_dump(), balance_after=account.balance, performed_by=current_user.id)\n    db.add(tx); db.commit(); db.refresh(tx)\n    return tx\n""",

    "admin_banners": """\"\"\"Admin banners router (wraps public banners router).\"\"\"\nfrom routers.banners import router\n""",

    "admin_settings": """\"\"\"Admin settings router.\"\"\"\nfrom fastapi import APIRouter, Depends\nfrom utils.dependencies import require_admin\nfrom utils.config import settings\nfrom db.models import User\n\nrouter = APIRouter()\n\n@router.get(\"/\")\ndef get_settings(_: User = Depends(require_admin)):\n    return {\n        \"app_name\": settings.APP_NAME,\n        \"version\": settings.APP_VERSION,\n        \"debug\": settings.DEBUG,\n        \"cors_origins\": settings.cors_origins_list,\n    }\n""",

    "logistics_partner": """\"\"\"Logistics partner profile router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import LogisticsPartnerProfile, User\nfrom db.schemas import LogisticsPartnerProfileCreate, LogisticsPartnerProfileOut\nfrom utils.dependencies import get_current_user, require_logistics\n\nrouter = APIRouter()\n\n@router.get(\"/profile\", response_model=LogisticsPartnerProfileOut)\ndef get_profile(current_user: User = Depends(require_logistics), db: Session = Depends(get_db)):\n    p = db.query(LogisticsPartnerProfile).filter(LogisticsPartnerProfile.user_id == current_user.id).first()\n    if not p: raise HTTPException(404)\n    return p\n\n@router.post(\"/profile\", response_model=LogisticsPartnerProfileOut, status_code=201)\ndef create_profile(payload: LogisticsPartnerProfileCreate, current_user: User = Depends(get_current_user), db: Session = Depends(get_db)):\n    if db.query(LogisticsPartnerProfile).filter(LogisticsPartnerProfile.user_id == current_user.id).first():\n        raise HTTPException(400, \"Profile already exists\")\n    p = LogisticsPartnerProfile(user_id=current_user.id, **payload.model_dump())\n    db.add(p); db.commit(); db.refresh(p)\n    current_user.role = \"logistics_partner\"; db.commit()\n    return p\n""",

    "logistics_orders": """\"\"\"Logistics partner orders router.\"\"\"\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\nfrom db.database import get_db\nfrom db.models import Shipment, LogisticsPartnerProfile, User\nfrom utils.dependencies import require_logistics\n\nrouter = APIRouter()\n\n@router.get(\"\")\ndef list_assigned_shipments(current_user: User = Depends(require_logistics), db: Session = Depends(get_db)):\n    partner = db.query(LogisticsPartnerProfile).filter(LogisticsPartnerProfile.user_id == current_user.id).first()\n    if not partner: raise HTTPException(404)\n    return db.query(Shipment).filter(Shipment.logistics_partner_id == partner.id).all()\n""",
}

os.makedirs(ROUTER_DIR, exist_ok=True)

for name, content in ROUTERS.items():
    path = os.path.join(ROUTER_DIR, f"{name}.py")
    if not os.path.exists(path):
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"Created: {name}.py")
    else:
        print(f"Skipped (exists): {name}.py")

print("Done.")
